def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b """
    # Handle edge cases for zero or negative numbers
    a, b = abs(a), abs(b)
    if a == 0:
        return b
    if b == 0:
        return a

    # Implement the Euclidean algorithm
    while b:
        a, b = b, a % b
    return a

