def fib4(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    fib_sequence = [0, 0, 2, 0]  # Initialize with the first four elements of the sequence

