def median(l: list):
    """Return median of elements in the list l."""
    # Sort the list
    l.sort()
    length = len(l)
    mid = length // 2
    if length == 0:
        return None
    elif length % 2 == 1:
        return l[mid]
    else:
        return (l[mid - 1] + l[mid]) / 2

