def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def count_numbers_starting_with_1(digit):
        return 9 * 10 ** (digit - 1)

    def count_numbers_ending_with_1(digit):
        return 10 ** (digit - 1)

    if n == 1:
        return 1

    count_starting_with_1 = count_numbers_starting_with_1(n) // 2
    count_ending_with_1 = count_numbers_ending_with_1(n) // 2
    overlap = 1

    return count_starting_with_1 + count_ending_with_1 - overlap

