def encode(message):
    encoded_message = ''

    for ch in message:
        if ch.isalpha():
            if ch.lower() in ['a', 'e', 'i', 'o', 'u']:
                encoded_message += chr(ord(ch) + 2)
            else:
                encoded_message += ch.swapcase()
        else:
            encoded_message += ch

    return encoded_message

