def count_up_to(n):
    """
    Return a list of prime numbers less than n using Sieve of Eratosthenes.
    """
    if n <= 1:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime

    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    primes = [i for i in range(2, n) if is_prime[i]]

    return primes

def closest_integer(value):
    """
    Return the closest integer to the given value.
    """
    number = float(value)
    floor_int = int(number)
    decimal_part = number - floor_int
    if decimal_part >= 0.5:
        return floor_int + 1
    elif decimal_part <= -0.5:
        return floor_int - 1
    else:
        return round(number)

