def rounded_avg(n, m):
    """
    Return the rounded average of integers from n to m in binary.
    """
    if n > m:
        return -1

    total_sum = sum(range(n, m+1))
    average = total_sum / (m - n + 1)  
    rounded_avg = round(average)

    return bin(rounded_avg)

