def histogram(test):
    counts = {}
    letters = test.split(" ")

    for letter in letters:
        if letter in counts:
            counts[letter] += 1
        else:
            counts[letter] = 1

    max_count = max(counts.values())
    max_letters = {k: v for k, v in counts.items() if v == max_count}

    return max_letters

