def do_algebra(operators, operands):
    """
    Given two lists operator, and operand. Build and evaluate the algebraic expression.
    """
    # Initialize result with the first operand
    result = operands[0]

    # Iterate over the operators and operands
    for i in range(len(operators)):
        operator = operators[i]
        operand = operands[i + 1]

        # Perform the algebraic operation based on the operator
        if operator == '+':
            result += operand
        elif operator == '-':
            result -= operand
        elif operator == '*':
            result *= operand
        elif operator == '//':
            result //= operand
        elif operator == '**':
            result **= operand

    return result

